package glitch

import data.glitch_lib
import future.keywords.in

credential_suffixes := {
    "password",
    "passwd",
    "pwd",
    "secret",
    "token",
}

keystore_patterns := {
    "keystore_password",
    "truststore_password",
}

blowfish_pattern := "blowfish_secret"

# Check if name ends with credential suffix (for _password patterns)
ends_with_credential(name) {
    lower_name := lower(name)
    suffix := credential_suffixes[_]
    endswith(lower_name, suffix)
}

# Check for keystore/truststore password patterns
is_keystore_credential(name) {
    lower_name := lower(name)
    pattern := keystore_patterns[_]
    contains(lower_name, pattern)
}

# Check for blowfish secret
is_blowfish_credential(name) {
    lower_name := lower(name)
    contains(lower_name, blowfish_pattern)
}

# Check if name is a credential field
has_credential_name(name) {
    ends_with_credential(name)
} else {
    is_keystore_credential(name)
} else {
    is_blowfish_credential(name)
}

is_not_reference(val) {
    lower_val := lower(val)
    not startswith(lower_val, "var.")
    not startswith(lower_val, "data.")
    not startswith(lower_val, "vault_")
    not startswith(val, "$")
    not startswith(val, "{{")
    not contains(lower_val, "lookup(")
    not contains(lower_val, "ansible_vault")
    not contains(lower_val, "secrets_manager")
    not contains(lower_val, "key_vault")
}

is_hardcoded_string(value) {
    value.ir_type == "String"
    value.value != ""
    count(value.value) >= 4
    is_not_reference(value.value)
}

# Recursively find credentials in any value structure
find_credentials_recursive(node) := results {
    results := {r |
        walk(node, [path, n])
        n.ir_type == "Hash"
        some entry in n.value
        entry.key.ir_type == "String"
        has_credential_name(entry.key.value)
        is_hardcoded_string(entry.value)
        r := {
            "key": entry.key.value,
            "value": entry.value,
            "path": path
        }
    }
}

# Variables from glitch_lib or direct access
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    some var in glitch_lib.all_variables(parent)
    has_credential_name(var.name)
    is_hardcoded_string(var.value)

    result := {
        "type": "sec_hard_secr",
        "element": var,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Credentials should not be hardcoded and should use external secret management. (CWE-798)"
    }
}

Glitch_Analysis[result] {
